602nc85.zh-cn:
/* 画布所有元素禁止响应鼠标事件 */
.smm-mind-map-container {
  pointer-events: none;
}
/* 超链接图标允许响应鼠标事件 */
.smm-node a {
  pointer-events: all;
}
/* 备注图标允许响应鼠标事件 */
.smm-node .smm-node-note {
  pointer-events: all;
}

gwzs8430.zh-cn:
/* 带下划线的文本内容全部隐藏 */
.smm-richtext-node-wrap u {
  opacity: 0;
}

qxmwilbp.zh-cn:
/* 鼠标hover和激活时渲染的矩形 */
.smm-hover-node{
  display: none;
  opacity: 0.6;
  stroke-width: 1;
}

.smm-node:not(.smm-node-dragging):hover .smm-hover-node{
  display: block;
}

.smm-node.active .smm-hover-node, .smm-node-highlight .smm-hover-node{
  display: block;
  opacity: 1;
  stroke-width: 2;
}

.smm-text-node-wrap, .smm-expand-btn-text {
  user-select: none;
}
